alue": {"adult": false, "id": "G10-O005", "options": [{"id": "agree", "text": "D’accord"}, {"id": "disagree", "text": "Pas d’accord"}], "text": "Les repas ratés donnent souvent les meilleurs souvenirs.", "theme": "Repas et goûts"}}, {"bank": "conv_opinion", "cv": "noodeu-g10-1.1.0", "idx": 5, "value": {"adult": false, "id": "G10-O006", "options": [{"id": "agree", "text": "D’accord"}, {"id": "disagree", "text": "Pas d’accord"}], "text": "Quand on aime vraiment une recette, on n’a pas besoin de la modifier.", "theme": "Repas et goûts"}}, {"bank": "conv_opinion", "cv": "noodeu-g10-1.1.0", "idx": 6, "value": {"adult": false, "id": "G10-O007", "options": [{"id": "agree", "text": "D’accord"}, {"id": "disagree", "text": "Pas d’accord"}], "text": "Le dessert se choisit avant le plat principal.", "theme": "Repas et goûts"}}, {"bank": "conv_opinion", "cv": "noodeu-g10-1.1.0", "idx": 7, "value": {"adult": false, "id": "G10-O008", "options": [{"id": "agree", "text": "D’accord"}, {"id": "disagree", "text": "Pas d’accord"}], "text": "Une belle présentation change vraiment le plaisir de manger.", "theme": "Repas et goûts"}}, {"bank": "conv_opinion", "cv": "noodeu-g10-1.1.0", "idx": 8, "value": {"adult": false, "id": "G10-O009", "options": [{"id": "agree", "text": "D’accord"}, {"id": "disagree", "text": "Pas d’accord"}], "text": "Pour faire découvrir sa cuisine préférée, un petit resto vaut mieux qu’une adresse réputée.", "theme": "Repas et goûts"}}, {"bank": "conv_opinion", "cv": "noodeu-g10-1.1.0", "idx": 9, "value": {"adult": false, "id": "G10-O010", "options": [{"id": "agree", "text": "D’accord"}, {"id": "disagree", "text": "Pas d’accord"}], "text": "Manger à une heure inhabituelle fait partie du plaisir des vacances.", "theme": "Repas et goûts"}}, {"bank": "conv_opinion", "cv": "noodeu-g10-1.1.0", "idx": 10, "value": {"adult": false, "id": "G10-O011", "options": [{"id": "agree", "text": "D’accord"}, {"id": "disagree", "text": "Pas d’accord"}], "text": "Un message lu mérite une réponse, même courte, dans la journée.", "theme": "Téléphone et réseaux"}}, {"bank": "conv_opinion", "cv": "noodeu-g10-1.1.0", "idx": 11, "value": {"adult": false, "id": "G10-O012", "options": [{"id": "agree", "text": "D’accord"}, {"id": "disagree", "text": "Pas d’accord"}], "text": "Envoyer plusieurs petits messages est plus agréable qu’un seul long pavé.", "theme": "Téléphone et réseaux"}}, {"bank": "conv_opinion", "cv": "noodeu-g10-1.1.0", "idx": 12, "value": {"adult": false, "id": "G10-O013", "options": [{"id": "agree", "text": "D’accord"}, {"id": "disagree", "text": "Pas d’accord"}], "text": "Un vocal de plus de deux minutes devrait commencer par un résumé.", "theme": "Téléphone et réseaux"}}, {"bank": "conv_opinion", "cv": "noodeu-g10-1.1.0", "idx": 13, "value": {"adult": false, "id": "G10-O014", "options": [{"id": "agree", "text": "D’accord"}, {"id": "disagree", "text": "Pas d’accord"}], "text": "Pendant un repas à deux, les téléphones devraient rester hors de vue.", "theme": "Téléphone et réseaux"}}, {"bank": "conv_opinion", "cv": "noodeu-g10-1.1.0", "idx": 14, "value": {"adult": false, "id": "G10-O015", "options": [{"id": "agree", "text": "D’accord"}, {"id": "disagree", "text": "Pas d’accord"}], "text": "Partager sa localisation au quotidien rassure plus que ça ne gêne.", "theme": "Téléphone et réseaux"}}, {"bank": "conv_opinion", "cv": "noodeu-g10-1.1.0", "idx": 15, "value": {"adult": false, "id": "G10-O016", "options": [{"id": "agree", "text": "D’accord"}, {"id": "disagree", "text": "Pas d’accord"}], "text": "Une photo réussie n’a pas besoin d’être publiée pour avoir de la valeur.", "theme": "Téléphone et réseaux"}}, {"bank": "conv_opinion", "cv": "noodeu-g10-1.1.0", "idx": 16, "value": {"adult": false, "id": "G10-O017", "options": [{"id": "agree", "text": "D’accord"}, {"id": "disagree", "text": "Pas d’accord"}], "text": "Un anniversaire souhaité en privé compte plus qu’une publication publique.", "theme": "Téléphone et réseaux"}}, {"bank": "conv_opinion", "cv": "noodeu-g10-1.1.0", "idx": 17, "value": {"adult": false, "id": "G10-O018", "options": [{"id": "agree", "text": "D’accord"}, {"id": "disagree", "text": "Pas d’accord"}], "text": "Quand un échange devient tendu par messages, il vaut mieux appeler tout de suite.", "theme": "Téléphone et réseaux"}}, {"bank": "conv_opinion", "cv": "noodeu-g10-1.1.0", "idx": 18, "value": {"adult": false, "id": "G10-O019", "options": [{"id": "agree", "text": "D’accord"}, {"id": "disagree", "text": "Pas d’accord"}], "text": "Un emoji peut suffire à répondre à un message affectueux.", "theme": "Téléphone et réseaux"}}, {"bank": "conv_opinion", "cv": "noodeu-g10-1.1.0", "idx": 19, "value": {"adult": false, "id": "G10-O020", "options": [{"id": "agree", "text": "D’accord"}, {"id": "disagree", "text": "Pas d’accord"}], "text": "Regarder une série ensemble à distance, c’est déjà passer une vraie soirée à deux.", "theme": "Téléphone et réseaux"}}, {"bank": "conv_opinion", "cv": "noodeu-g10-1.1.0", "idx": 20, "value": {"adult": false, "id": "G10-O021", "options": [{"id": "agree", "text": "D’accord"}, {"id": "disagree", "text": "Pas d’accord"}], "text": "Revoir un film qu’on connaît par cœur est plus reposant que choisir une nouveauté.", "theme": "Culture et loisirs"}}, {"bank": "conv_opinion", "cv": "noodeu-g10-1.1.0", "idx": 21, "value": {"adult": false, "id": "G10-O022", "options": [{"id": "agree", "text": "D’accord"}, {"id": "disagree", "text": "Pas d’accord"}], "text": "Une série qui met cinq épisodes à devenir intéressante demande trop d’efforts.", "theme": "Culture et loisirs"}}, {"bank": "conv_opinion", "cv": "noodeu-g10-1.1.0", "idx": 22, "value": {"adult": false, "id": "G10-O023", "options": [{"id": "agree", "text": "D’accord"}, {"id": "disagree", "text": "Pas d’accord"}], "text": "La musique est meilleure quand on peut chanter dessus.", "theme": "Culture et loisirs"}}, {"bank": "conv_opinion", "cv": "noodeu-g10-1.1.0", "idx": 23, "value": {"adult": false, "id": "G10-O024", "options": [{"id": "agree", "text": "D’accord"}, {"id": "disagree", "text": "Pas d’accord"}], "text": "Un concert reste réussi même si l’artiste ne joue pas son plus gros titre.", "theme": "Culture et loisirs"}}, {"bank": "conv_opinion", "cv": "noodeu-g10-1.1.0", "idx": 24, "value": {"adult": false, "id": "G10-O025", "options": [{"id": "agree", "text": "D’accord"}, {"id": "disagree", "text": "Pas d’accord"}], "text": "Connaître la fin d’un film gâche forcément une partie du plaisir.", "theme": "Culture et loisirs"}}, {"bank": "conv_opinion", "cv": "noodeu-g10-1.1.0", "idx": 25, "value": {"adult": false, "id": "G10-O026", "options": [{"id": "agree", "text": "D’accord"}, {"id": "disagree", "text": "Pas d’accord"}], "text": "Les jeux sont plus drôles quand on prend le score au sérieux.", "theme": "Culture et loisirs"}}, {"bank": "conv_opinion", "cv": "noodeu-g10-1.1.0", "idx": 26, "value": {"adult": false, "id": "G10-O027", "options": [{"id": "agree", "text": "D’accord"}, {"id": "disagree", "text": "Pas d’accord"}], "text": "On peut aimer une chanson sans aimer l’artiste qui la chante.", "theme": "Culture et loisirs"}}, {"bank": "conv_opinion", "cv": "noodeu-g10-1.1.0", "idx": 27, "value": {"adult": false, "id": "G10-O028", "options": [{"id": "agree", "text": "D’accord"}, {"id": "disagree", "text": "Pas d’accord"}], "text": "Un loisir n’a pas besoin de nous faire progresser pour mériter du temps.", "theme": "Culture et loisirs"}}, {"bank": "conv_opinion", "cv": "noodeu-g10-1.1.0", "idx": 28, "value": {"adult": false, "id": "G10-O029", "options": [{"id": "agree", "text": "D’accord"}, {"id": "disagree", "text": "Pas d’accord"}], "text": "Une sortie gratuite peut donner plus de souvenirs qu’un événement cher.", "theme": "Culture et loisirs"}}, {"bank": "conv_opinion", "cv": "noodeu-g10-1.1.0", "idx": 29, "value": {"adult": false, "id": "G10-O030", "options": [{"id": "agree", "text": "D’accord"}, {"id": "disagree", "text": "Pas d’accord"}], "text": "Un film triste est un bon choix pour une soirée où on a le moral bas.", "theme": "Culture et loisirs"}}, {"bank": "conv_opinion", "cv": "noodeu-g10-1.1.0", "idx": 30, "value": {"adult": false, "id": "G10-O031", "options": [{"id": "agree", "text": "D’accord"}, {"id": "disagree", "text": "Pas d’accord"}], "text": "Dans un couple, garder chacun une activité sans l’autre aide à se retrouver.", "theme": "Relations et autonomie"}}, {"bank": "conv_opinion", "cv": "noodeu-g10-1.1.0", "idx": 31, "value": {"adult": false, "id": "G10-O032", "options": [{"id": "agree", "text": "D’accord"}, {"id": "disagree", "text": "Pas d’accord"}], "text": "Une petite attention régulière compte plus qu’un gros geste exceptionnel.", "theme": "Relations et autonomie"}}, {"bank": "conv_opinion", "cv": "noodeu-g10-1.1.0", "idx": 32, "value": {"adult": false, "id": "G10-O033", "options": [{"id": "agree", "text": "D’accord"}, {"id": "disagree", "text": "Pas d’accord"}], "text": "Il vaut mieux dire directement qu’on est vexé que laisser l’autre le deviner.", "theme": "Relations et autonomie"}}, {"bank": "conv_opinion", "cv": "noodeu-g10-1.1.0", "idx": 33, "value": {"adult": false, "id": "G10-O034", "options": [{"id": "agree", "text": "D’accord"}, {"id": "disagree", "text": "Pas d’accord"}], "text": "Des vacances séparées peuvent faire du bien à un couple.", "theme": "Relations et autonomie"}}, {"bank": "conv_opinion", "cv": "noodeu-g10-1.1.0", "idx": 34, "value": {"adult": false, "id": "G10-O035", "options": [{"id": "agree", "text": "D’accord"}, {"id": "disagree", "text": "Pas d’accord"}], "text": "Les amis proches devraient pouvoir dire franchement qu’une relation les inquiète.", "theme": "Relations et autonomie"}}, {"bank": "conv_opinion", "cv": "noodeu-g10-1.1.0", "idx": 35, "value": {"adult": false, "id": "G10-O036", "options": [{"id": "agree", "text": "D’accord"}, {"id": "disagree", "text": "Pas d’accord"}], "text": "Un couple n’a pas besoin de se parler tous les jours pour rester proche.", "theme": "Relations et autonomie"}}, {"bank": "conv_opinion", "cv": "noodeu-g10-1.1.0", "idx": 36, "value": {"adult": false, "id": "G10-O037", "options": [{"id": "agree", "text": "D’accord"}, {"id": "disagree", "text": "Pas d’accord"}], "text": "Faire une activité qu’on n’aime pas pour faire plaisir à l’autre en vaut la peine.", "theme": "Relations et autonomie"}}, {"bank": "conv_opinion", "cv": "noodeu-g10-1.1.0", "idx": 37, "value": {"adult": false, "id": "G10-O038", "options": [{"id": "agree", "text": "D’accord"}, {"id": "disagree", "text": "Pas d’accord"}], "text": "On apprend davantage sur quelqu’un pendant un imprévu que pendant un rendez-vous parfait.", "theme": "Relations et autonomie"}}, {"bank": "conv_opinion", "cv": "noodeu-g10-1.1.0", "idx": 38, "value": {"adult": false, "id": "G10-O039", "options": [{"id": "agree", "text": "D’accord"}, {"id": "disagree", "text": "Pas d’accord"}], "text": "Garder une amitié avec un ex peut être simple.", "theme": "Relations et autonomie"}}, {"bank": "conv_opinion", "cv": "noodeu-g10-1.1.0", "idx": 39, "value": {"adult": false, "id": "G10-O040", "options": [{"id": "agree", "text": "D’accord"}, {"id": "disagree", "text": "Pas d’accord"}], "text": "Un désaccord mérite parfois une nuit de recul avant d’être discuté.", "theme": "Relations et autonomie"}}, {"bank": "conv_opinion", "cv": "noodeu-g10-1.1.0", "idx": 40, "value": {"adult": false, "id": "G10-O041", "options": [{"id": "agree", "text": "D’accord"}, {"id": "disagree", "text": "Pas d’accord"}], "text": "Un cadeau choisi avec soin touche plus qu’un cadeau coûteux.", "theme": "Argent et vie quotidienne"}}, {"bank": "conv_opinion", "cv": "noodeu-g10-1.1.0", "idx": 41, "value": {"adult": false, "id": "G10-O042", "options": [{"id": "agree", "text": "D’accord"}, {"id": "disagree", "text": "Pas d’accord"}], "text": "Quand deux personnes gagnent des sommes différentes, partager les frais à moitié est injuste.", "theme": "Argent et vie quotidienne"}}, {"bank": "conv_opinion", "cv": "noodeu-g10-1.1.0", "idx": 42, "value": {"adult": false, "id": "G10-O043", "options": [{"id": "agree", "text": "D’accord"}, {"id": "disagree", "text": "Pas d’accord"}], "text": "Prêter de l’argent à un proche complique souvent la relation.", "theme": "Argent et vie quotidienne"}}, {"bank": "conv_opinion", "cv": "noodeu-g10-1.1.0", "idx": 43, "value": {"adult": false, "id": "G10-O044", "options": [{"id": "agree", "text": "D’accord"}, {"id": "disagree", "text": "Pas d’accord"}], "text": "Il vaut mieux payer pour gagner du temps que tout faire soi-même.", "theme": "Argent et vie quotidienne"}}, {"bank": "conv_opinion", "cv": "noodeu-g10-1.1.0", "idx": 44, "value": {"adult": false, "id": "G10-O045", "options": [{"id": "agree", "text": "D’accord"}, {"id": "disagree", "text": "Pas d’accord"}], "text": "Un achat plaisir n’a pas besoin d’être utile.", "theme": "Argent et vie quotidienne"}}, {"bank": "conv_opinion", "cv": "noodeu-g10-1.1.0", "idx": 45, "value": {"adult": false, "id": "G10-O046", "options": [{"id": "agree", "text": "D’accord"}, {"id": "disagree", "text": "Pas d’accord"}], "text": "Dans un logement partagé, les tâches devraient tourner même si chacun a ses préférences.", "theme": "Argent et vie quotidienne"}}, {"bank": "conv_opinion", "cv": "noodeu-g10-1.1.0", "idx": 46, "value": {"adult": false, "id": "G10-O047", "options": [{"id": "agree", "text": "D’accord"}, {"id": "disagree", "text": "Pas d’accord"}], "text": "Un objet qu’on utilise tous les jours mérite qu’on y mette le prix.", "theme": "Argent et vie quotidienne"}}, {"bank": "conv_opinion", "cv": "noodeu-g10-1.1.0", "idx": 47, "value": {"adult": false, "id": "G10-O048", "options": [{"id": "agree", "text": "D’accord"}, {"id": "disagree", "text": "Pas d’accord"}], "text": "Préparer une liste avant les courses enlève une partie du plaisir.", "theme": "Argent et vie quotidienne"}}, {"bank": "conv_opinion", "cv": "noodeu-g10-1.1.0", "idx": 48, "value": {"adult": false, "id": "G10-O049", "options": [{"id": "agree", "text": "D’accord"}, {"id": "disagree", "text": "Pas d’accord"}], "text": "Après un dîner entre amis, les invités devraient aider à ranger avant de partir.", "theme": "Argent et vie quotidienne"}}, {"bank": "conv_opinion", "cv": "noodeu-g10-1.1.0", "idx": 49, "value": {"adult": false, "id": "G10-O050", "options": [{"id": "agree", "text": "D’accord"}, {"id": "disagree", "text": "Pas d’accord"}], "text": "Mieux vaut réparer un objet moyen que le remplacer par un modèle plus beau.", "theme": "Argent et vie quotidienne"}}, {"bank": "conv_opinion", "cv": "noodeu-g10-1.1.0", "idx": 50, "value": {"adult": false, "id": "G10-O051", "options": [{"id": "agree", "text": "D’accord"}, {"id": "disagree", "text": "Pas d’accord"}], "text": "Une sortie improvisée est plus mémorable qu’une sortie organisée depuis un mois.", "theme": "Sorties et voyages"}}, {"bank": "conv_opinion", "cv": "noodeu-g10-1.1.0", "idx": 51, "value": {"adult": false, "id": "G10-O052", "options": [{"id": "agree", "text": "D’accord"}, {"id": "disagree", "text": "Pas d’accord"}], "text": "Partir tôt vaut la fatigue si ça permet d’avoir le lieu presque pour soi.", "theme": "Sorties et voyages"}}, {"bank": "conv_opinion", "cv": "noodeu-g10-1.1.0", "idx": 52, "value": {"adult": false, "id": "G10-O053", "options": [{"id": "agree", "text": "D’accord"}, {"id": "disagree", "text": "Pas d’accord"}], "text": "Pour un premier voyage à deux, un week-end suffit.", "theme": "Sorties et voyages"}}, {"bank": "conv_opinion", "cv": "noodeu-g10-1.1.0", "idx": 53, "value": {"adult": false, "id": "G10-O054", "options": [{"id": "agree", "text": "D’accord"}, {"id": "disagree", "text": "Pas d’accord"}], "text": "En vacances, mieux vaut voir moins de lieux et prendre son temps.", "theme": "Sorties et voyages"}}, {"bank": "conv_opinion", "cv": "noodeu-g10-1.1.0", "idx": 54, "value": {"adult": false, "id": "G10-O055", "options": [{"id": "agree", "text": "D’accord"}, {"id": "disagree", "text": "Pas d’accord"}], "text": "Prendre beaucoup de photos aide à prof